'use strict';
// Synthetic-only exact forwarding checks. No payloads are printed.
const fs=require('fs'),https=require('https'),crypto=require('crypto'),zlib=require('zlib'),assert=require('assert');
const cases=['normal','request-malformed','response-malformed','request-compressed','response-compressed','request-oversized','response-oversized','request-chunked','response-chunked','request-trailer','response-trailer','response-409'];
const normal=Buffer.from('{"probe":true}'), reply=Buffer.from('{"id":1}'), malformed=Buffer.from('{"probe":'), huge=Buffer.from('{"probe":"'+ 'synthetic-secret-sentinel-'+ 'x'.repeat(65536)+'"}');
function body(name,direction){if(name===direction+'-malformed')return malformed;if(name===direction+'-oversized')return huge;if(name===direction+'-compressed')return zlib.gzipSync(direction==='request'?normal:reply);return direction==='request'?normal:reply;}
function digest(x){return crypto.createHash('sha256').update(x).digest('hex');}
function checked(req,expected,done){let n=0,chunks=[];req.on('data',b=>{n+=b.length;if(n>70000){req.destroy();return;}chunks.push(b);});req.on('error',()=>process.exitCode=1);req.on('end',()=>{try{assert.deepStrictEqual(Buffer.concat(chunks),expected);done();}catch(_){process.exitCode=1;req.destroy();}});}
if(process.argv[2]==='server'){
 const expected=process.env.EXPECTED_CLIENT_SHA256;
 const server=https.createServer({cert:fs.readFileSync('/fixture/destination.crt'),key:fs.readFileSync('/fixture/destination.key'),ca:fs.readFileSync('/fixture/ca.crt'),requestCert:true,rejectUnauthorized:true},(req,res)=>{
  try{assert(req.socket.authorized);assert.equal(digest(req.socket.getPeerCertificate(true).raw),expected);assert.equal(req.method,'POST');assert.equal(req.url,'/pilot');const name=req.headers['x-fixture-case'];assert(cases.includes(name));assert.equal(req.headers['content-encoding'],name==='request-compressed'?'gzip':undefined);
   checked(req,body(name,'request'),()=>{try{assert.equal(req.trailers['x-fixture-end'],name==='request-trailer'?'done':undefined);const out=body(name,'response'),headers={'content-type':'application/json'};if(name==='response-compressed')headers['content-encoding']='gzip';if(name==='response-trailer')headers.trailer='x-fixture-end';else if(name!=='response-chunked')headers['content-length']=out.length;res.writeHead(name==='response-409'?409:200,headers);if(name==='response-chunked'){res.write(out.subarray(0,3));res.end(out.subarray(3));}else if(name==='response-trailer'){res.write(out);res.addTrailers({'x-fixture-end':'done'});res.end();}else res.end(out);}catch(_){res.destroy();process.exitCode=1;}});
  }catch(_){res.destroy();process.exitCode=1;}
 });server.listen(9444,'127.0.0.1',()=>process.stdout.write('READY 9444\n'));const stop=()=>{server.close(()=>process.exit(process.exitCode||0));server.closeAllConnections();};process.on('SIGTERM',stop);process.on('SIGINT',stop);
}else if(process.argv[2]==='client'){
 const name=process.argv[3];if(!cases.includes(name))throw Error('case');const payload=body(name,'request'),headers={'content-type':'application/json','x-fixture-case':name,'te':'trailers'};if(name==='request-compressed')headers['content-encoding']='gzip';if(name==='request-trailer')headers.trailer='x-fixture-end';else if(name!=='request-chunked')headers['content-length']=payload.length;
 const req=https.request({host:'127.0.0.1',port:9443,servername:'pilot-destination',path:'/pilot',method:'POST',ca:fs.readFileSync('/fixture/ca.crt'),cert:fs.readFileSync('/fixture/client.crt'),key:fs.readFileSync('/fixture/client.key'),rejectUnauthorized:true,headers},res=>{try{assert.equal(res.statusCode,name==='response-409'?409:200);assert.equal(res.headers['content-encoding'],name==='response-compressed'?'gzip':undefined);checked(res,body(name,'response'),()=>{try{assert.equal(res.trailers['x-fixture-end'],name==='response-trailer'?'done':undefined);process.stdout.write('OK\n');}catch(_){process.exitCode=1;}});}catch(_){res.destroy();process.exitCode=1;}});req.setTimeout(10000,()=>req.destroy());req.on('error',()=>{process.exitCode=1;});if(name==='request-chunked'){req.write(payload.subarray(0,3));req.end(payload.subarray(3));}else if(name==='request-trailer'){req.write(payload);req.addTrailers({'x-fixture-end':'done'});req.end();}else req.end(payload);
}else throw Error('mode');
